```js
export function bounceOffBricks(state, prevX, prevY) {
  const ball = state.ball;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;
  if (dx === 0 && dy === 0) return false;

  // Sweep the ball from (prevX, prevY) to (ball.x, ball.y) against each live brick.
  // The brick box is inflated by the ball radius (ball treated as a circle box).
  // Slab method returns the entry parameter t and the axis (x/y) of the entry face.
  let hits = [];
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const hit = sweepBrick(prevX, prevY, ball.x, ball.y, ball.r, brick);
    if (hit) hits.push({ brick, t: hit.t, axis: hit.axis, normal: hit.normal });
  }
  if (hits.length === 0) return false;

  // Sort by entry time; resolve the earliest crossings together.
  hits.sort((a, b) => a.t - b.t);
  const firstT = hits[0].t;
  let flippedX = false, flippedY = false;
  for (const h of hits) {
    if (h.t > firstT + EPS) break;   // only the earliest crossings in this pass
    h.brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(h.brick, state.combo);
    if (h.axis === 'x' && !flippedX) {
      ball.vx = -ball.vx;  // hmm — which sign?
      flippedX = true;
    } else if (h.axis === 'y' && !flippedY) {
      ball.vy = -ball.vy;
      flippedY = true;
    }
  }
  // Push the ball out along the entry face of the earliest hit... 
}
```

