// --- Brick collision (swept, per-face) -------------------------------------

// Swept collision: does the ball's path from (px, py) to (cx, cy) cross the
// brick? The ball is its AABB (consistent with collides()); the brick box
// inflated by the ball radius is exactly the set of centers where the ball
// overlaps the brick. The slab method returns the entry parameter `t` and the
// axis of the face first crossed, or null when the path misses the brick.
function sweepHit(px, py, cx, cy, r, brick) {
  const dx = cx - px;
  const dy = cy - py;
  const x0 = brick.x - r;
  const x1 = brick.x + brick.w + r;
  const y0 = brick.y - r;
  const y1 = brick.y + brick.h + r;

  let txEnter, txExit;
  if (dx === 0) {
    if (cx < x0 || cx > x1) return null;
    txEnter = -Infinity;
    txExit = Infinity;
  } else {
    const t1 = (x0 - px) / dx;
    const t2 = (x1 - px) / dx;
    txEnter = Math.min(t1, t2);
    txExit = Math.max(t1, t2);
  }
  let tyEnter, tyExit;
  if (dy === 0) {
    if (cy < y0 || cy > y1) return null;
    tyEnter = -Infinity;
    tyExit = Infinity;
  } else {
    const t1 = (y0 - py) / dy;
    const t2 = (y1 - py) / dy;
    tyEnter = Math.min(t1, t2);
    tyExit = Math.max(t1, t2);
  }

  const tEnter = Math.max(txEnter, tyEnter);
  const tExit = Math.min(txExit, tyExit);
  if (tEnter > tExit || tExit < 0 || tEnter > 1) return null;

  // Entry face: which slab was entered last?
  if (tEnter === txEnter && tEnter === tyEnter) return { t: tEnter, axis: 'both' };
  if (tEnter === txEnter) return { t: tEnter, axis: 'x' };
  return { t: tEnter, axis: 'y' };
}
```

