export function bounceOffBricks(state, prevX, prevY) {
  const ball = state.ball;
  const hits = [];
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const hit = sweepHit(prevX, prevY, ball.x, ball.y, ball.r, brick);
    if (hit) hits.push({ brick, ...hit });
  }
  if (hits.length === 0) return false;

  hits.sort((a, b) => a.t - b.t);
  const first = hits[0];
  const firstT = first.t;

  let flippedX = false;
  let flippedY = false;
  let bounced = false;

  for (const h of hits) {
    if (h.t > firstT + EPS) break;
    h.brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(h.brick, state.combo);
    const axes = faceAxes(h, ball);   // 'x' | 'y' | 'both'
    if (axes.x && !flippedX) { ball.vx = -ball.vx; flippedX = true; bounced = true; }
    if (axes.y && !flippedY) { ball.vy = -ball.vy; flippedY = true; bounced = true; }
  }

