```js
function sweepBrick(px, py, cx, cy, r, brick) {
  const dx = cx - px;
  const dy = cy - py;
  const x0 = brick.x - r;
  const x1 = brick.x + brick.w + r;
  const y0 = brick.y - r;
  const y1 = brick.y + brick.h + r;

  let txEnter, txExit;
  if (dx === 0) {
    if (cx < x0 || cx > x1) return null;
    txEnter = -Infinity;
    txExit = Infinity;
  } else {
    const t1 = (x0 - px) / dx;
    const t2 = (x1 - px) / dx;
    txEnter = Math.min(t1, t2);
    txExit = Math.max(t1, t2);
  }
  let tyEnter, tyExit;
  if (dy === 0) {
    if (cy < y0 || cy > y1) return null;
    tyEnter = -Infinity;
    tyExit = Infinity;
  } else {
    const t1 = (y0 - py) / dy;
    const t2 = (y1 - py) / dy;
    tyEnter = Math.min(t1, t2);
    tyExit = Math.max(t1, t2);
  }

  const tEnter = Math.max(txEnter, tyEnter);
  const tExit = Math.min(txExit, tyExit);
  if (tEnter > tExit || tExit < 0 || tEnter > 1) return null;
  if (tEnter < 0) return { t: tEnter, axis: 'sticky', dx, dy };

  const eps = 1e-9;
  const atX = Math.abs(tEnter - txEnter) < eps;
  const atY = Math.abs(tEnter - tyEnter) < eps;
  const axis = atX && atY ? 'both' : atX ? 'x' : 'y';
  return { t: tEnter, axis, dx, dy };
}
