// neon.test.js — coverage: collision primitive, physics bounces, and the
// swept brick/paddle resolution (bounceOffBricks, step). Pure logic, no DOM.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  bounceOffBricks,
  makeBricks,
  createState,
  scoreForBrick,
  ballSpeed,
  BRICK_ROWS,
  BRICK_COLS,
  BRICK_TOP,
  BRICK_H,
  BRICK_GAP,
  PADDLE_Y,
  BALL_R,
  WIDTH,
} from './neon.js';

// --- Static collision primitive --------------------------------------------

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

// --- step(): walls, bottom loss, paddle ------------------------------------

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('step: fast descending ball is caught by the paddle (no tunneling)', () => {
  // Level 6 speed × dt(50 ms) = 710 × 0.05 = 35.5 px > PADDLE_H + 2·BALL_R
  // (12 + 14 = 26 px): the ball would jump over the paddle in one step.
  const state = createState(6);
  state.ball = { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 3, r: BALL_R, vx: 0, vy: 1000 };
  const lost = step(state, 0.05);
  assert.equal(lost, false, 'a fast ball crossing the paddle top is not lost');
  assert.ok(state.ball.vy < 0, 'vy flips back up');
  assert.equal(state.ball.y, PADDLE_Y - BALL_R, 'the ball exits from the top of the paddle');
});

// --- bounceOffBricks(): swept, per-face brick collision --------------------

// Row-0 brick geometry (offsetX = 4): col 3 is x∈[244,316], col 4 is x∈[324,396].

test('brick bounce: ball under a brick is deflected off its bottom face', () => {
  const state = createState(1);
  const brick = state.bricks.find((b) => b.row === 0);
  const cx = brick.x + brick.w / 2;
  // One frame ago the ball was 8 px lower, moving up (vy < 0); it now overlaps
  // the brick from below.
  state.ball = { x: cx, y: brick.y + brick.h + BALL_R - 3, r: BALL_R, vx: 0, vy: -300 };
  bounceOffBricks(state, cx, state.ball.y + 8);
  assert.equal(brick.alive, false, 'the brick is destroyed');
  assert.ok(state.ball.vy > 0, 'vy flips from UP to DOWN');
  assert.equal(state.ball.y, brick.y + brick.h + BALL_R, 'ball pushed below the brick');
  assert.equal(collides(state.ball, brick), false, 'ball no longer overlaps the brick');
});

test('brick bounce: ball above a brick is deflected off its top face', () => {
  const state = createState(1);
  const brick = state.bricks.find((b) => b.row === 0);
  const cx = brick.x + brick.w / 2;
  state.ball = { x: cx, y: brick.y - BALL_R + 3, r: BALL_R, vx: 0, vy: 300 };
  bounceOffBricks(state, cx, state.ball.y - 8);
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vy < 0, 'vy flips from DOWN to UP');
  assert.equal(state.ball.y, brick.y - BALL_R, 'ball pushed above the brick');
  assert.equal(collides(state.ball, brick), false);
