test('brick bounce: ball beside a brick is deflected off its side face', () => {
  const state = createState(1);
  const brick = state.bricks.find((b) => b.row === 0);
  const cy = brick.y + brick.h / 2;
  state.ball = { x: brick.x - BALL_R + 3, y: cy, r: BALL_R, vx: 300, vy: 0 };
  bounceOffBricks(state, state.ball.x - 8, cy);
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vx < 0, 'vx flips from RIGHT to LEFT');
  assert.equal(state.ball.x, brick.x - BALL_R, 'ball pushed left of the brick');
  assert.equal(collides(state.ball, brick), false);
