test('brick bounce: ball speed magnitude is preserved', () => {
  const state = createState(1);
  const brick = state.bricks.find((b) => b.row === 0);
  const cx = brick.x + brick.w / 2;
  state.ball = { x: cx, y: brick.y + brick.h + BALL_R - 3, r: BALL_R, vx: 130, vy: -260 };
  const speedBefore = Math.hypot(state.ball.vx, state.ball.vy);
  bounceOffBricks(state, cx, state.ball.y + 8);
  assert.equal(brick.alive, false);
