      bounceOffBricks(state, px, py);
    }
    return { brick, ball: state.ball };
  }
  const slow = run(1 / 30, 10);
  const fast = run(1 / 144, 50);
  assert.equal(slow.brick.alive, false, '30 fps: the brick is hit');
  assert.equal(fast.brick.alive, false, '144 fps: the brick is hit');
  assert.ok(slow.ball.vy > 0, '30 fps: ball bounces down');
  assert.ok(fast.ball.vy > 0, '144 fps: ball bounces down');
  assert.ok(slow.ball.y > slow.brick.y + slow.brick.h, '30 fps: ball below the brick');
  assert.ok(fast.ball.y > fast.brick.y + fast.brick.h, '144 fps: ball below the brick');
});

test('brick bounce: seam between two bricks flips vy exactly once', () => {
  // The ball crosses the seam between two adjacent bricks of the same row in
  // one pass: two naive `vy = -vy` would cancel and the ball would plow on.
  const state = createState(1);
  const b3 = state.bricks.find((b) => b.y === BRICK_TOP && b.x === 244);
  const b4 = state.bricks.find((b) => b.y === BRICK_TOP && b.x === 324);
  const seamX = 320; // right edge of col 3 (316) .. left edge of col 4 (324)
  state.ball = { x: seamX, y: BRICK_TOP + BRICK_H + BALL_R - 3, r: BALL_R, vx: 0, vy: -300 };
  bounceOffBricks(state, seamX, state.ball.y + 8);
  assert.equal(b3.alive, false, 'left brick of the seam destroyed');
  assert.equal(b4.alive, false, 'right brick of the seam destroyed');
  assert.equal(state.ball.vy, 300, 'vy flipped exactly once (no double inversion)');
  assert.equal(state.ball.y, BRICK_TOP + BRICK_H + BALL_R, 'ball pushed below the row');
});

test('brick bounce: corner hit flips both components', () => {
  // The path enters the inflated brick box exactly through its top-left
  // corner (brick.x - BALL_R, brick.y - BALL_R): a coin hit.
  const state = createState(1);
  const brick = state.bricks.find((b) => b.row === 0); // col 0: x∈[4,76]
  state.ball = { x: brick.x - 3, y: brick.y - 3, r: BALL_R, vx: 200, vy: 200 };
  bounceOffBricks(state, state.ball.x - 5, state.ball.y - 5);
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vx < 0, 'vx flips on a corner hit');
  assert.ok(state.ball.vy < 0, 'vy flips on a corner hit');
});

test('brick bounce: brick counted once, combo and score consistent', () => {
  const state = createState(1);
  const b3 = state.bricks.find((b) => b.y === BRICK_TOP && b.x === 244);
  const b4 = state.bricks.find((b) => b.y === BRICK_TOP && b.x === 324);
  const seamX = 320;
  state.ball = { x: seamX, y: BRICK_TOP + BRICK_H + BALL_R - 3, r: BALL_R, vx: 0, vy: -300 };
  const before = { score: state.score, combo: state.combo };
  bounceOffBricks(state, seamX, state.ball.y + 8);
  assert.equal(state.combo, before.combo + 2, 'one combo point per destroyed brick');
  assert.equal(
    state.score,
    before.score + scoreForBrick(b3, 1) + scoreForBrick(b4, 2),
    'score uses the running combo'
  );
  // A second pass over the same path must not re-count anything.
  bounceOffBricks(state, seamX, state.ball.y + 8);
  assert.equal(state.combo, before.combo + 2, 'no double counting');
  assert.equal(state.score, before.score + scoreForBrick(b3, 1) + scoreForBrick(b4, 2));
});

