test('brick bounce: same outcome at 30 fps and 144 fps (no dt dependence)', () => {
  function run(dt, frames) {
    const state = createState(1);
    const brick = state.bricks.find((b) => b.row === 1);
    clearColumnBelow(state, brick);
    const cx = brick.x + brick.w / 2;
    state.ball = { x: cx, y: brick.y + brick.h + BALL_R + 30, r: BALL_R, vx: 0, vy: -ballSpeed(1) };
    for (let i = 0; i < frames; i++) {
      const px = state.ball.x;
      const py = state.ball.y;
      const lost = step(state, dt);
      if (lost) break;
      bounceOffBricks(state, px, py);
    }
    return { brick, ball: state.ball };
  }
  const slow = run(1 / 30, 10);
  const fast = run(1 / 144, 50);
  assert.equal(slow.brick.alive, false, '30 fps: the brick is hit');
