content.text:
// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The bounce itself lives in bounceOffBricks() below.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Brick collision (swept, per-face) -------------------------------------

// Swept test: does the ball path (px,py) → (cx,cy) cross the brick? The ball
// is its AABB (same approximation as collides()), so the brick box inflated by
// the ball radius is exactly the set of ball centers whose AABB overlaps the
// brick. The slab method returns the first crossing: `t` (entry time along the
// segment, < 0 when the pass started inside the brick), the `axis` of the
// entry face ('x', 'y', 'both' for a corner entry, or 'sticky' when the pass
// began already overlapping), and the movement `dx`/`dy`. Returns null when
// the path misses the brick entirely.
function sweepBrick(px, py, cx, cy, r, brick) {
  const dx = cx - px;
  const dy = cy - py;
  const x0 = brick.x - r;
  const x1 = brick.x + brick.w + r;
  const y0 = brick.y - r;
  const y1 = brick.y + brick.h + r;

  let txEnter;
  let txExit;
  if (dx === 0) {
    if (cx < x0 || cx > x1) return null;
    txEnter = -Infinity;
    txExit = Infinity;
  } else {
    const t1 = (x0 - px) / dx;
    const t2 = (x1 - px) / dx;
    txEnter = Math.min(t1, t2);
    txExit = Math.max(t1, t2);
  }
  let tyEnter;
  let tyExit;
  if (dy === 0) {
    if (cy < y0 || cy > y1) return null;
    tyEnter = -Infinity;
    tyExit = Infinity;
  } else {
    const t1 = (y0 - py) / dy;
    const t2 = (y1 - py) / dy;
    tyEnter = Math.min(t1, t2);
    tyExit = Math.max(t1, t2);
  }

  const tEnter = Math.max(txEnter, tyEnter);
  const tExit = Math.min(txExit, tyExit);
  if (tEnter > tExit || tExit < 0 || tEnter > 1) return null;
  if (tEnter < 0) return { t: tEnter, axis: 'sticky', dx, dy };

  const eps = 1e-9;
  const atX = Math.abs(tEnter - txEnter) < eps;
  const atY = Math.abs(tEnter - tyEnter) < eps;
  const axis = atX && atY ? 'both' : atX ? 'x' : 'y';
  return { t: tEnter, axis, dx, dy };
}

// Face of the brick the ball path entered through, expressed as flip axes and
// push-out sides. `sideX`/`sideY` are -1 (push out to the left/top) or +1
// (push out to the right/bottom).
function entryFace(hit) {
  const face = { x: false, y: false, sideX: 0, sideY: 0 };
  if (hit.axis === 'x' || hit.axis === 'both') {
    face.x = true;
    face.sideX = hit.dx > 0 ? -1 : 1;
  }
  if (hit.axis === 'y' || hit.axis === 'both') {
    face.y = true;
    face.sideY = hit.dy > 0 ? -1 : 1;
  }
  return face;
}

// Fallback for a pass that started inside the brick (should not happen once
// every bounce pushes the ball out, but a side push can land on a neighbour):
// leave through the face with the smallest penetration, flipping both axes on
// a corner tie.
function stickyFace(ball, brick) {
  const r = ball.r;
  const penTop = ball.y + r - brick.y;
  const penBottom = brick.y + brick.h - (ball.y - r);
  const penLeft = ball.x + r - brick.x;
  const penRight = brick.x + brick.w - (ball.x - r);
  const min = Math.min(penTop, penBottom, penLeft, penRight);
  const eps = 1e-6;
  const face = { x: false, y: false, sideX: 0, sideY: 0 };
  if (Math.abs(penTop - min) < eps) { face.y = true; face.sideY = -1; }
  if (Math.abs(penBottom - min) < eps) { face.y = true; face.sideY = 1; }
  if (Math.abs(penLeft - min) < eps) { face.x = true; face.sideX = -1; }
  if (Math.abs(penRight - min) < eps) { face.x = true; face.sideX = 1; }
  return face;
}

// Resolves the ball against every live brick crossed since the last frame.
// Swept (no tunneling), per-face (entry face / smallest penetration, both
// components at a corner), pushes the ball back out (no sticky re-inversion)
// and flips each velocity component at most once per pass (no double
// inversion on a seam). Returns true if the ball bounced off at least one
// brick.
export function bounceOffBricks(state, prevX, prevY) {
  const ball = state.ball;
  const hits = [];
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const hit = sweepBrick(prevX, prevY, ball.x, ball.y, ball.r, brick);
    if (hit) hits.push({ brick, ...hit });
  }
  if (hits.length === 0) return false;

  // Resolve only the earliest crossings: after the first bounce the ball
  // travels in a new direction, so later crossings of the same straight
  // segment are no longer part of its actual path.
  hits.sort((a, b) => a.t - b.t);
  const firstT = hits[0].t;
  const EPS = 1e-9;
  let flippedX = false;
  let flippedY = false;
  let bounced = false;

  for (const h of hits) {
    if (h.t > firstT + EPS) break;
    const face = h.axis === 'sticky' ? stickyFace(ball, h.brick) : entryFace(h);
    h.brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(h.brick, state.combo);
    if (face.x && !flippedX) {
      ball.vx = -ball.vx;
      flippedX = true;
      bounced = true;
    }
    if (face.y && !flippedY) {
      ball.vy = -ball.vy;
      flippedY = true;
      bounced = true;
    }
    if (face.x) {
      ball.x = face.sideX < 0 ? h.brick.x - ball.r : h.brick.x + h.brick.w + ball.r;
    }
    if (face.y) {
      ball.y = face.sideY < 0 ? h.brick.y - ball.r : h.brick.y + h.brick.h + ball.r;
    }
  }
  return bounced;
}

// --- Score & combo (NOT covered by tests — debt #5) ------------------------

// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

// Points earned for breaking a brick, combo included.
export function scoreForBrick(brick, combo) {
  return Math.round(brick.points * comboMultiplier(combo));
}

// --- Best score persistence ------------------------------------------------

// Reads the best score from a localStorage-compatible storage.
// Robust to corrupted or missing storage: returns 0 instead of throwing.
export function loadBest(storage) {
  if (!storage) return 0;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) && value > 0 ? value : 0;
  } catch {
